import { useState } from 'react';
import { Button, Card, Modal } from '@helixds/react';

export function TaskScreen() {
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);

  const handleDeleteClick = () => {
    setIsDeleteModalOpen(true);
  };

  const handleConfirmDelete = () => {
    setIsDeleteModalOpen(false);
    console.log('Account deleted');
  };

  const handleCancelDelete = () => {
    setIsDeleteModalOpen(false);
  };

  return (
    <div className="p-6">
      <Card className="max-w-2xl">
        <div className="space-y-4">
          <h2 className="text-lg font-semibold">Account Settings</h2>
          <p className="text-sm text-gray-600">Manage your account and preferences</p>

          <div className="border-t pt-4">
            <div className="space-y-2">
              <h3 className="font-medium">Delete Account</h3>
              <p className="text-sm text-gray-600">
                Once you delete your account, there is no going back. Please be certain.
              </p>
              <Button
                variant="danger"
                onClick={handleDeleteClick}
              >
                Delete Account
              </Button>
            </div>
          </div>
        </div>
      </Card>

      <Modal
        expanded={isDeleteModalOpen}
        onExpandedChange={setIsDeleteModalOpen}
      >
        <div className="space-y-4">
          <div>
            <h2 className="text-lg font-semibold">Delete Account?</h2>
            <p className="mt-2 text-sm text-gray-600">
              Are you absolutely sure? This action cannot be undone. Your account and all associated data will be permanently deleted.
            </p>
          </div>

          <div className="flex gap-3 justify-end">
            <Button
              variant="secondary"
              onClick={handleCancelDelete}
            >
              Cancel
            </Button>
            <Button
              variant="danger"
              onClick={handleConfirmDelete}
            >
              Delete Account
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
}

